"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[12855],{3331:(e,r,n)=>{n.d(r,{R:()=>o,x:()=>a});var t=n(36672);const i={},s=t.createContext(i);function o(e){const r=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(s.Provider,{value:r},e.children)}},85883:(e,r,n)=>{n.r(r),n.d(r,{assets:()=>l,contentTitle:()=>a,default:()=>g,frontMatter:()=>o,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"2023/04/07","title":"2023-04-07","description":"Hvis vi mister Internett-arkivet, er vi ferdige.","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/07.md","sourceDirName":"2023/04","slug":"/2023/04/07","permalink":"/nb/2023/04/07","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/07.md","tags":[],"version":"current","frontMatter":{"localized_date":"7. april 2023","top_news":"Hvis vi mister Internett-arkivet, er vi ferdige."},"sidebar":"defaultSidebar","previous":{"title":"2023-04-08","permalink":"/nb/2023/04/08"},"next":{"title":"2023-04-06","permalink":"/nb/2023/04/06"}}');var i=n(23420),s=n(3331);const o={localized_date:"7. april 2023",top_news:"Hvis vi mister Internett-arkivet, er vi ferdige."},a="2023-04-07",l={},d=[{value:"Hvis vi mister Internett-arkivet, er vi ferdige.",id:"hvis-vi-mister-internett-arkivet-er-vi-ferdige",level:2},{value:"Chrome leverer WebGPU",id:"chrome-leverer-webgpu",level:2},{value:"Vis Tabby - En GitHub Copilot som er vert for seg selv",id:"vis-tabby---en-github-copilot-som-er-vert-for-seg-selv",level:2},{value:"Tesla-arbeidere delte bilder fra bilkameraer, inkludert &quot;intimscener&quot;.",id:"tesla-arbeidere-delte-bilder-fra-bilkameraer-inkludert-intimscener",level:2},{value:"Enkelt forklart: Hvordan fungerer GPT?",id:"enkelt-forklart-hvordan-fungerer-gpt",level:2},{value:"Systemdesign og kostnadene ved arkitektonisk kompleksitet (2013)",id:"systemdesign-og-kostnadene-ved-arkitektonisk-kompleksitet-2013",level:2},{value:"Baktalt av ChatGPT",id:"baktalt-av-chatgpt",level:2},{value:"Hovedplan del 3",id:"hovedplan-del-3",level:2},{value:"Tesla-arbeidere delte sensitive bilder tatt opp av kundebiler Tesla-arbeidere delte sensitive bilder tatt opp av kundebiler",id:"tesla-arbeidere-delte-sensitive-bilder-tatt-opp-av-kundebiler-tesla-arbeidere-delte-sensitive-bilder-tatt-opp-av-kundebiler",level:2},{value:"Buck2: V\xe5rt byggesystem med \xe5pen kildekode",id:"buck2-v\xe5rt-byggesystem-med-\xe5pen-kildekode",level:2},{value:"Mariadb.com er d\xf8d, lenge leve MariaDB.org.",id:"mariadbcom-er-d\xf8d-lenge-leve-mariadborg",level:2},{value:"Vis ADHD-vennlig Pomodoro web-app",id:"vis-adhd-vennlig-pomodoro-web-app",level:2},{value:"Meta lanserer nytt AI-basert fotosegmenteringsverkt\xf8y for alle",id:"meta-lanserer-nytt-ai-basert-fotosegmenteringsverkt\xf8y-for-alle",level:2},{value:"Hva skjer n\xe5r du lekker AWS-legitimasjon og hvordan AWS minimerer skaden",id:"hva-skjer-n\xe5r-du-lekker-aws-legitimasjon-og-hvordan-aws-minimerer-skaden",level:2},{value:"Gource - Animer Git-historikken din.",id:"gource---animer-git-historikken-din",level:2},{value:"Vis Generer oppstartsideer basert p\xe5 Discussion Service-kommentarer.",id:"vis-generer-oppstartsideer-basert-p\xe5-discussion-service-kommentarer",level:2},{value:"DevOps bruker en kapasitetsmodell, ikke en modenhetsmodell.",id:"devops-bruker-en-kapasitetsmodell-ikke-en-modenhetsmodell",level:2},{value:"Det er ingen enkel oppgave \xe5 \xf8ke kapasiteten i str\xf8mnettet.",id:"det-er-ingen-enkel-oppgave-\xe5-\xf8ke-kapasiteten-i-str\xf8mnettet",level:2},{value:"Vi kunngj\xf8r WCGI: WebAssembly og CGI",id:"vi-kunngj\xf8r-wcgi-webassembly-og-cgi",level:2},{value:"JSON vs. XML",id:"json-vs-xml",level:2},{value:"Nettstedet ligger p\xe5 en 24 \xe5r gammel Linux-server.",id:"nettstedet-ligger-p\xe5-en-24-\xe5r-gammel-linux-server",level:2},{value:"Er det min feil hvis du ikke takler sannheten? (2019)",id:"er-det-min-feil-hvis-du-ikke-takler-sannheten-2019",level:2},{value:"C Strings og min langsomme nedstigning til galskap",id:"c-strings-og-min-langsomme-nedstigning-til-galskap",level:2},{value:"MutexProtected: Et C++-m\xf8nster for enklere samtidighet",id:"mutexprotected-et-c-m\xf8nster-for-enklere-samtidighet",level:2},{value:"Clarence Thomas og milliard\xe6ren",id:"clarence-thomas-og-milliard\xe6ren",level:2},{value:"Rusts d\xe5rlige komposisjonsevne",id:"rusts-d\xe5rlige-komposisjonsevne",level:2},{value:"Oppdage og unng\xe5 heap-fragmentering i Rust-applikasjoner",id:"oppdage-og-unng\xe5-heap-fragmentering-i-rust-applikasjoner",level:2},{value:"V\xe6r forsiktig med hva du tester eller distribuerer til Vercel",id:"v\xe6r-forsiktig-med-hva-du-tester-eller-distribuerer-til-vercel",level:2},{value:"Linux 6.4 Bringer Apple M2-tillegg for 2022 MacBook og Mac Mini",id:"linux-64-bringer-apple-m2-tillegg-for-2022-macbook-og-mac-mini",level:2},{value:"Illustrasjoner av &quot;usynlige&quot; japanske vedlikeholdstog som bare kj\xf8rer om natten.",id:"illustrasjoner-av-usynlige-japanske-vedlikeholdstog-som-bare-kj\xf8rer-om-natten",level:2}];function k(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"2023-04-07",children:"2023-04-07"})}),"\n",(0,i.jsx)(r.h2,{id:"hvis-vi-mister-internett-arkivet-er-vi-ferdige",children:"Hvis vi mister Internett-arkivet, er vi ferdige."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.sbstatesman.com/2023/04/04/if-we-lose-the-internet-archive-were-screwed/",children:"Original"}),'.\nInternet Archive, som beskriver seg selv som "et ikke-kommersielt bibliotek med millioner av gratis b\xf8ker, filmer, programvare, musikk, nettsteder og mer", har blitt saks\xf8kt av fire utgivere for brudd p\xe5 opphavsretten, og en f\xf8deral dommer har gitt utgiverne medhold. Internet Archive anker imidlertid avgj\xf8relsen, som noen hevder i bunn og grunn er et angrep p\xe5 skattefinansierte offentlige tjenester fra selskaper og privatpersoner. Kritikere hevder at nedleggelsen av det nasjonale n\xf8dbiblioteket, som gjorde opphavsrettsbeskyttede b\xf8ker tilgjengelig gratis under covid-19-pandemien, er langt mer katastrofalt for arbeiderklassen enn tilgang til b\xf8ker noen gang kan bli. Hvis appellen mislykkes, vil mennesker miste mer kunnskap enn det Alexandra-biblioteket noen gang inneholdt.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468753",children:"Discussion Service"}),".\nDiscussion Service-brukere debatterer opphavsrettslover og kulturbevaring. Juridiske kamper reiser sp\xf8rsm\xe5l om opphavsrettens legitimitet og statlige monopoler. Noen etterlyser bedre styring for \xe5 oppmuntre til arbeid og kortere opphavsrettsperioder. \xc5 miste IA kan omskrive historien og fremheve viktigheten av \xe5 bevare kunnskap. Forslag om \xe5 starte en ny enhet eller stoppe donasjoner p\xe5 grunn av IAs risikable oppf\xf8rsel. Nasjonalt beredskapsbibliotek sett p\xe5 som uventet og gunstig, men IA-ledere har et ansvar for \xe5 bevare historien."]}),"\n",(0,i.jsx)(r.h2,{id:"chrome-leverer-webgpu",children:"Chrome leverer WebGPU"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://developer.chrome.com/blog/webgpu-release/",children:"Original"}),'.\nChrome lanserer WebGPU, et nytt nettgrafikk-API som tilbyr forbedret 3D-grafikk og dataparallell beregning p\xe5 ChromeOS, macOS og Windows, for \xe5 gi tilgang til avanserte GPU-funksjoner og effektiv programmering med nettplattformen. WebGPU er designet med et idiomatisk JavaScript-API, integrasjon med l\xf8fter og gode feilmeldinger, og det er en byggestein for fremtidige forbedringer, for eksempel tilgang til skyggekjerner for mer maskinl\xe6ringsoptimalisering og bedre ergonomi i WGSL. WebGPU er resultatet av et 6-\xe5rig samarbeid mellom W3Cs "GPU for the Web" Community Group, inkludert bidrag fra Mozilla, Apple, Intel og Microsoft. ChromeOS-, Windows- og macOS-plattformene kan st\xf8tte WebGPU, med Linux, Android og andre plattformer som utvider st\xf8tten i n\xe6r fremtid. Popul\xe6re WebGL-biblioteker, som Babylon.js, PlayCanvas og TensorFlow.js, tilbyr allerede noe WebGPU-st\xf8tte eller jobber med det. Ressurser for \xe5 l\xe6re mer om WebGPU inkluderer blant annet W3C-spesifikasjoner, MDN-dokumentasjon, eksempler og GPU-beregning.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35465729",children:"Discussion Service"}),".\nChrome har levert WebGPU, som lover forbedringer i forhold til WebGL. WebGPU er en game changer med positive bidrag; meningene varierer om hvorvidt stasjon\xe6re eller mobile GPUer b\xf8r prioriteres. Brukerne diskuterer m\xe5ter \xe5 begrense nettleserfunksjoner som lekker informasjon og forhindre fingeravtrykk. Det er bekymring for potensiell ondsinnet bruk til utvinning av kryptovaluta. Web3DSurvey sporer funksjoner og begrensninger knyttet til WebGPU. Det er spenning knyttet til potensialet for at WebGPU kan bli tatt i bruk i stor skala, til tross for bekymringer om begrensninger sammenlignet med mer kapable grafikkteknologier."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-tabby---en-github-copilot-som-er-vert-for-seg-selv",children:"Vis Tabby - En GitHub Copilot som er vert for seg selv"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://github.com/TabbyML/tabby",children:"Original"}),".\nTabbyML har gitt ut Tabby, et selvdrevet alternativ til GitHub Copilot som er \xe5pen kildekode og on-prem. Det har selvinneslutning uten behov for en DBMS eller skytjeneste, et nettgrensesnitt for visualisering og konfigurasjonsmodeller og MLOps, et OpenAPI-grensesnitt og enkel integrering med eksisterende infrastruktur. Utviklere kan bruke docker-bildet for enkel distribusjon, og TabbyML st\xf8tter GPU p\xe5 forbrukerniv\xe5 med FP-16 vektbelastning og andre optimaliseringer. FastAPI-serveren inneholder en OpenAPI-dokumentasjon av HTTP API."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35470915",children:"Discussion Service"}),".\nTabby, et selvhostet GitHub Copilot-alternativ, tilbyr full kontroll over data og personvern mens du finjusterer modeller. Det sparer tid, men reiser bekymringer for personvernet. GitHubs personvernproblemer er overdrevne, og Copilot har begrensninger. TabbyML genererer standardkode og reiser sp\xf8rsm\xe5l om IP-sikring av koden. Alpha-versjonen av Tabby er popul\xe6r til tross for mangel p\xe5 profesjonell presentasjon og dokumentasjon. Copilot forutsier kode n\xf8yaktig, men har begrensninger og kan foresl\xe5 d\xe5rlig kode. Noen brukere foresl\xe5r en egenhostet versjon av Copilot og navneendring for bedre SEO."]}),"\n",(0,i.jsx)(r.h2,{id:"tesla-arbeidere-delte-bilder-fra-bilkameraer-inkludert-intimscener",children:'Tesla-arbeidere delte bilder fra bilkameraer, inkludert "intimscener".'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://arstechnica.com/tech-policy/2023/04/tesla-workers-shared-images-from-car-cameras-including-scenes-of-intimacy/",children:"Original"}),'.\nTesla-ansatte delte angivelig videoer og bilder tatt av kundebilkameraer gjennom et internt meldingssystem, som inkluderte "noen ganger sv\xe6rt invasivt" innhold. Til tross for at Tesla hevdet at bilkameraene er "designet fra grunnen av for \xe5 beskytte personvernet", hadde de ansatte enkel tilgang til kameraene og delte innholdet "fritt". Intime scener som ikke inneholder nakenhet, sammen med "visse t\xf8ystykker og visse seksuelle velv\xe6reartikler", var blant elementene som ble delt. Noen tidligere ansatte hevdet imidlertid at det var legitim deling i jobbsammenheng. Alternativt ble noen bilder angivelig delt bredt og sett av mange, inkludert ledelsen.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35471826",children:"Discussion Service"}),'.\nBrukere diskuterer dupliserte artikler og retningslinjer for innsending av originalkilder. Ingen relevante kommentarer om temaet Tesla som deler bilder fra bilkameraer, inkludert "intimscener".']}),"\n",(0,i.jsx)(r.h2,{id:"enkelt-forklart-hvordan-fungerer-gpt",children:"Enkelt forklart: Hvordan fungerer GPT?"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://confusedbit.dev/posts/how_does_gpt_work/",children:"Original"}),".\nArtikkelen diskuterer prosessen bak GPT-3 og hvordan den brukes til naturlige spr\xe5ksamtaler gjennom innbygging av ord og probabilistiske modeller. Dens styrker inkluderer generering av tekst og logisk sammenkobling av ideer, men st\xe5r overfor begrensninger med falsk informasjon og inndatarestriksjoner. Det er likheter og forskjeller med den menneskelige hjernens struktur, inkludert GPTs begrensede spr\xe5kevner og mangel p\xe5 kontinuerlig l\xe6ring. Artikkelen tar ogs\xe5 opp bevissthetssp\xf8rsm\xe5l og bekymringer om tap av arbeidsplasser, men bemerker at GPT alene ikke kan gj\xf8re skade. Forsiktighet er imidlertid n\xf8dvendig for videre utvikling av kunstig intelligens, og eksperter unders\xf8ker m\xe5ter \xe5 forhindre negative resultater p\xe5. Tekniske ferdigheter og entrepren\xf8r\xe5nd vil v\xe6re verdifullt ettersom konsekvensene av GPT fortsatt er usikre."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35466201",children:"Discussion Service"}),".\nHacker News-eksperter diskuterer AI-spr\xe5kmodellenes muligheter og begrensninger, inkludert ChatGPT og GPT-4. Noen er forsiktige med \xe5 tillegge maskiner menneskelignende egenskaper, men ChatGPT produserer n\xf8yaktig og kontekstspesifikk tekst, en del av AGI. Debatt rundt Chinese Room-scenariets relevans og arten av intelligens og bevissthet. Oppmerksomhet gitt til praktiske evner og innovasjon, relevans av transformatorer og begrensninger av treningsdata. Skeptikere bemerker at GPT-4 mangler tilbakemeldingsmekanismer for biologiske hjerner til tross for at den genererer menneskelignende tekst."]}),"\n",(0,i.jsx)(r.h2,{id:"systemdesign-og-kostnadene-ved-arkitektonisk-kompleksitet-2013",children:"Systemdesign og kostnadene ved arkitektonisk kompleksitet (2013)"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://dspace.mit.edu/handle/1721.1/79551",children:"Original"}),'.\nFeilmeldingen "HTTP Status 429 - Too Many Requests" indikerer at brukeren har sendt mange foresp\xf8rsler p\xe5 kort tid.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35470905",children:"Discussion Service"}),".\nArtikkelen diskuterer systemdesign og kostnadene ved arkitektonisk kompleksitet. Brukere deler personlige erfaringer med skyleverand\xf8rer og forst\xe5else av komplekse systemer. Kommentarene fremhever viktigheten av enkelhet, god dokumentasjon og \xe5 tenke fremover. Fordelene og utfordringene ved programvarearkitektur, og balansen mellom enkelhet og kompleksitet, diskuteres av eksperter. Definisjonen av kompleksitet i programvaresystemer diskuteres ogs\xe5."]}),"\n",(0,i.jsx)(r.h2,{id:"baktalt-av-chatgpt",children:"Baktalt av ChatGPT"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://jonathanturley.org/2023/04/06/defamed-by-chatgpt-my-own-bizarre-experience-with-artificiality-of-artificial-intelligence/",children:"Original"}),".\nN/A."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468540",children:"Discussion Service"}),".\nAI-genererte injurier utgj\xf8r en betydelig risiko, og ChatGPT granskes for sitt potensielle ansvar. Brukerne diskuterer ansvaret for resultatene og foresl\xe5r \xe5 opprettholde en standard for aktsomhet. Ansvarssp\xf8rsm\xe5l knyttet til selvkj\xf8rende biler diskuteres ogs\xe5, og de juridiske implikasjonene av ChatGPT som et verkt\xf8y for \xe5 s\xf8ke medisinsk og juridisk r\xe5dgivning. Det er ogs\xe5 uttrykt bekymring for spr\xe5kmodellenes n\xf8yaktighet og den etiske bruken av personopplysninger. Det er reist kritikk mot ChatGPTs p\xe5litelighet og spredning av feilinformasjon, noe som har f\xf8rt til krav om ansvarsfraskrivelser og bindende tjenesteavtaler. Skj\xe6ringspunktet mellom teknologi og samfunn er et hovedfokus i dette innlegget, med p\xe5g\xe5ende juridiske debatter om ansvarlighet for AI-genererte resultater."]}),"\n",(0,i.jsx)(r.h2,{id:"hovedplan-del-3",children:"Hovedplan del 3"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.tesla.com/blog/master-plan-part-3",children:"Original"}),".\nTesla lanserer Master Plan Part 3, som foresl\xe5r en vei til en b\xe6rekraftig global energi\xf8konomi gjennom elektrifisering og elektrisitetsproduksjon og -lagring, med detaljerte forutsetninger, kilder og beregninger bak forslaget. Leserne er velkomne til \xe5 komme med innspill og delta i samtalen. Tesla leverer ogs\xe5 den amerikanske fullelektrifiserte ettersp\xf8rselsprofilen som brukes i modelleringen."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35462378",children:"Discussion Service"}),".\nTeslas masterplan del 3 f\xe5r oppmerksomhet p\xe5 Hacker News med diskusjoner om fossilfri livsstil, gjennomf\xf8rbarheten av elbiler, investeringer i fornybar energi og spredningen av covid-19. Brukerne diskuterer det praktiske ved \xe5 g\xe5 over til fornybar energi, den \xf8konomiske skattebyrden for de superrike og bruken av vennlighet og toleranse som v\xe5pen i politikken. Teslas omd\xf8mme, behandling av ansatte og visjoner for fremtiden diskuteres ogs\xe5. Redakt\xf8ren m\xe5 identifisere hovedbudskapet og unng\xe5 politiske eller religi\xf8se fordommer."]}),"\n",(0,i.jsx)(r.h2,{id:"tesla-arbeidere-delte-sensitive-bilder-tatt-opp-av-kundebiler-tesla-arbeidere-delte-sensitive-bilder-tatt-opp-av-kundebiler",children:"Tesla-arbeidere delte sensitive bilder tatt opp av kundebiler Tesla-arbeidere delte sensitive bilder tatt opp av kundebiler"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.reuters.com/technology/tesla-workers-shared-sensitive-images-recorded-by-customer-cars-2023-04-06/",children:"Original"}),'.\nTesla-ansatte delte sensitive videoer tatt opp av kundebilkameraer mellom 2019 og 2022, if\xf8lge Reuters-intervjuer med ni tidligere Tesla-arbeidere. Ulykker, raseri og pinlige situasjoner var blant videoene som ble delt gjennom Teslas interne meldingssystem, noen offentlig. Selskapets personvernerkl\xe6ring fremhever anonymitetssikringen av kameraopptak som ikke er knyttet til kunder eller kj\xf8ret\xf8yene deres, men noen tidligere ansatte kalte det et "brudd p\xe5 personvernet". Tesla svarte p\xe5 databeskyttelseshensyn ved \xe5 gj\xf8re endringer i Sentry Mode, inkludert pulserende frontlykter p\xe5 parkerte biler for \xe5 varsle forbipasserende om at de kan bli overv\xe5ket. Reuters hevder at alle sitater vil bli forsinket, og det gir lenker for rettelser og tilbakemeldinger p\xe5 nettstedet.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468855",children:"Discussion Service"}),".\nTesla-arbeidere delte sensitive bilder tatt opp av kundebiler uten personverntiltak. Personvernregler med alvorlige konsekvenser b\xf8r h\xe5ndheves, og selskaper m\xe5 bygge personvern fra grunnen av. Anekdoter fremhever mangel p\xe5 personvern i ulike selskaper og oppstartsbedrifter, og Indias mangel p\xe5 digitale personvernlover kritiseres. Personvernet er ikke helt sikkert, og ansatte kan se og misbruke private data. De tyske personvernstandardene er ikke perfekte, men databeskyttelsesmyndighetene vil v\xe6re interessert i eventuelle datainnbrudd fra bilprodusentene p\xe5 grunn av h\xe5ndhevelsen av personvernforordningen. Det er personvernproblemer med tilkoblede kj\xf8ret\xf8y, men noen bemerker at lignende sporingsmuligheter finnes i andre kj\xf8ret\xf8y enn elbiler. Rapporter tyder p\xe5 at noen utl\xe5nere har plassert sporingsenheter p\xe5 biler, selv om det er uklart om de selger dataene."]}),"\n",(0,i.jsx)(r.h2,{id:"buck2-v\xe5rt-byggesystem-med-\xe5pen-kildekode",children:"Buck2: V\xe5rt byggesystem med \xe5pen kildekode"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://engineering.fb.com/2023/04/06/open-source/buck2-open-source-large-scale-build-system/",children:"Original"}),".\nMeta lanserer Buck2, et byggesystem med \xe5pen kildekode p\xe5 GitHub, skrevet i Rust. Buck2 skiller kjerne- og spr\xe5kspesifikke regler, med interne tester som indikerer bygger 2x raskere enn Buck1, \xf8kt parallellisme og en redesignet konsollutgang. Buck2 kan v\xe6re egnet for flerspr\xe5klige prosjekter av moderat st\xf8rrelse, designet med avanserte funksjoner for ytelse og uttrykksfulle, dynamiske avhengighetsfunksjoner. Meta deler teknologiprosjekter med \xe5pen kildekode, inkludert AI, data, utvikling, front-end, spr\xe5k, plattformer, sikkerhet og VR, uten nevneverdige oppdateringer eller utgivelser nevnt."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35470371",children:"Discussion Service"}),".\nFacebooks \xe5pen kildekode-byggesystem Buck2 f\xe5r oppmerksomhet for sin inkrementelle beregningsmotor og Windows-st\xf8tte. Discussion Service-brukere diskuterer andre byggeverkt\xf8y, inkludert Waf, TensorFlow og Py_wheel, og fremhever utfordringene med \xe5 h\xe5ndtere store kodebaser. Buck2 fjerner JVM-avhengighet i Buck1 ved \xe5 skrive den om i Rust. Buck2 og Bazel er flerspr\xe5klige build-systemer med reproduserbare builds og integrasjonsmuligheter. Artikkelen foresl\xe5r \xe5 bruke riktig verkt\xf8y for riktig jobb, og fokusere p\xe5 et verkt\xf8ys styrker. Noen brukere hevder at statisk kompilering \xf8ker kompleksiteten, mens andre argumenterer for fordelene med statisk koblede bin\xe6re filer."]}),"\n",(0,i.jsx)(r.h2,{id:"mariadbcom-er-d\xf8d-lenge-leve-mariadborg",children:"Mariadb.com er d\xf8d, lenge leve MariaDB.org."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://medium.com/@imashadowphantom/mariadb-com-is-dead-long-live-mariadb-org-b8a0ca50a637",children:"Original"}),".\nMariaDB.com, den kommersielle enheten, st\xe5r overfor feil p\xe5 grunn av d\xe5rlig ledelse, rasisme, sexisme og brudd p\xe5 arbeidsretten. Monty, grunnleggeren, ble fjernet fra styret i juli 2022, og administrerende direkt\xf8r Michael Howards fiendtlige overtakelse f\xf8rte til en nedgang i aksjeverdien. SEC-arkivering indikerer at MariaDB kan legge ned, og st\xe5r overfor problemer med \xe5 beholde og rekruttere personell p\xe5 grunn av omd\xf8mmet. Ansatte r\xe5des til \xe5 planlegge intervjuer med andre selskaper, samtidig som de roser MariaDB.org og \xe5pen kildekode."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467243",children:"Discussion Service"}),".\nNedleggelsen av MariaDB.com f\xf8rer til mistanke om \xf8konomisk ustabilitet. P\xe5stander om partiskhet og ubegrunnede anklager mot MariaDB Corp. blir m\xf8tt med skepsis. Offentligheten er delt i synet p\xe5 MariaDB.orgs fremtid. Hacker News-tr\xe5den diskuterer p\xe5stander om diskriminering, skifter til sammenligning av MariaDB og Postgres. MariaDB Corporation s\xf8ker konkurs, innvirkningen p\xe5 utviklingen er usikker. MariaDB PLCs aksjer faller med nesten 70% siden b\xf8rsnoteringen, analytikernes bekymring over uerfaren ledelse og bransjeendringer. S\xf8ksm\xe5lstap p\xe5 20 millioner dollar og SkySQL-fusjon bidrar til \xf8konomiske problemer. Fremtidig utvikling bekymringer ubegrunnet p\xe5 grunn av bedriftssponsorer."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-adhd-vennlig-pomodoro-web-app",children:"Vis ADHD-vennlig Pomodoro web-app"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://brainpls.work/",children:"Original"}),".\nSiden dette bare er en kommentar p\xe5 \xe9n linje, er det dessverre ikke nok informasjon til \xe5 gi et kortfattet sammendrag."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35471129",children:"Discussion Service"}),".\n'Brainpls.work' Pomodoro-basert tidtaker for ADHD-st\xf8tte kritiseres for \xe5 v\xe6re nettbasert. Forslag til smartere timer-enhet og forbedringer av nettleser-appen. Ny app for oppmerksomhet/flyt-timer utgitt p\xe5 Github, foretrukket som egen app. Brukere roser personlig flashcard-app som sporer fremgang. Tilbakemeldinger inkluderer \xe5 legge til lydvarsler, distraksjonsmarkering og visning av lokal tid. Apputvikleren kan ha ADHD."]}),"\n",(0,i.jsx)(r.h2,{id:"meta-lanserer-nytt-ai-basert-fotosegmenteringsverkt\xf8y-for-alle",children:"Meta lanserer nytt AI-basert fotosegmenteringsverkt\xf8y for alle"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://arstechnica.com/information-technology/2023/04/meta-introduces-ai-model-that-can-isolate-and-mask-objects-within-images/",children:"Original"}),".\nMeta har utviklet en ny bildesegmenteringsmodell kalt SAM som kan isolere ethvert objekt i bilder eller videoer p\xe5 kommando. SAM tar sikte p\xe5 \xe5 demokratisere bildesegmenteringsprosessen ved \xe5 redusere behovet for spesialisert oppl\xe6ring og ekspertise. Teknologien er egnet for forst\xe5else av innhold p\xe5 nettsider, bilderedigering og applikasjoner for utvidet virkelighet. SAM er bemerkelsesverdig for sin evne til \xe5 identifisere objekter som ikke er til stede i treningsdatasettet og sin delvis \xe5pne tiln\xe6rming. I tillegg har Meta laget et datasett kalt SA-1B som inneholder 11 millioner bilder og 1,1 milliarder segmenteringsmasker som vil bli gjort tilgjengelig for forskningsform\xe5l under en Apache 2.0-lisens."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468304",children:"Discussion Service"}),".\nMeta lanserer AI-basert bildesegmenteringsverkt\xf8y med ros for \xe5penhet og AI-utvikling. Noen bekymrer seg for plattformens levedyktighet. Modell trent p\xe5 12,6 millioner bilder med \xe5pen kildekode. Brukere kritiserer misvisende artikkeltittel og eksisterende segmenteringsverkt\xf8y. Ingen relevans for Chrome-utvidelse eller YC-applikasjoner."]}),"\n",(0,i.jsx)(r.h2,{id:"hva-skjer-n\xe5r-du-lekker-aws-legitimasjon-og-hvordan-aws-minimerer-skaden",children:"Hva skjer n\xe5r du lekker AWS-legitimasjon og hvordan AWS minimerer skaden"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://xebia.com/blog/what-happens-when-you-leak-aws-credentials-and-how-aws-minimizes-the-damage/",children:"Original"}),'.\nEn AWS-bruker lekket med vilje AWS-legitimasjonen sin til et offentlig GitHub-depot for \xe5 se hva som ville skje. I l\xf8pet av et minutt etter at legitimasjonen ble lekket, la AWS til en "karantenepolicy" til brukerkontoen og informerte brukeren via e-post med instruksjoner om hvordan de skulle sikre kontoen sin. En ondsinnet akt\xf8r foretok raskt automatiserte API-anrop med den lekkede p\xe5loggingsinformasjonen, men lyktes ikke p\xe5 grunn av begrensede tillatelser. AWS bruker en GitHub Secrets Scanning-tjeneste for raskt \xe5 oppdage og reagere p\xe5 lekket p\xe5loggingsinformasjon. For \xe5 forhindre lekkasje av p\xe5loggingsinformasjon kan brukerne kj\xf8re skanninger f\xf8r godkjenning lokalt eller legge til en hemmelig skanner i CI/CD-pipelinen.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35466675",children:"Discussion Service"}),".\nEn Discussion Service-bruker satte opp et prosjekt for automatisk \xe5 lekke AWS-hemmeligheter og utl\xf8se skanneprosesser. Det er frustrerende \xe5 rotere n\xf8kler med mange p\xe5 en konto. AWS ugyldiggj\xf8r tokens i offentlige depoter, men kjeltringer kan allerede ha tilgang. AWS-brukere anbefales \xe5 snakke med teamet f\xf8r de tilbakekaller n\xf8kler i produksjon. AWS-brukerst\xf8tte b\xf8r kontaktes s\xe5 snart som mulig etter et angrep. Ytterligere sikkerhet kan legges til ved \xe5 begrense n\xf8kkelbruk til bestemte IP-adresser. Et skript eller en git-krok kan forhindre pushing av legitimasjon. Skannerens programmeringshensikt er uklar."]}),"\n",(0,i.jsx)(r.h2,{id:"gource---animer-git-historikken-din",children:"Gource - Animer Git-historikken din."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://gource.io/",children:"Original"}),".\nGource er en animert tregrafikkgenerator for programvareprosjektkataloger som utviklere kan jobbe med. Verkt\xf8yet har innebygd loggst\xf8tte for Git, Mercurial, Bazaar og SVN, og kan analysere logger laget av tredjepartsverkt\xf8y for CVS-arkiver. Gource har omfattende dokumentasjon, eksempler og kontroller p\xe5 sin wiki-side, som inkluderer nye funksjoner, fonter, filtre og alternativer som --high-dpi-alternativet, --file-idle-time-at-end-alternativet eller --fixed-user-size-alternativet. Gource 0.54 er den nyeste versjonen, som inkluderer eksperimentell st\xf8tte for Wayland og feilrettinger p\xe5 Apple M1. Det finnes andre lignende verkt\xf8y som Logstalgia, sett p\xe5 som et nyttig visualiseringsverkt\xf8y for webservertilgangslogg. Hvis du liker Gource, kan du vise din takknemlighet og donere til forfatteren for \xe5 oppmuntre til fremtidig utvikling av dette og andre prosjekter med \xe5pen kildekode."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35471420",children:"Discussion Service"}),".\nGource, et verkt\xf8y for \xe5 animere Git-historikk, f\xe5r skryt for \xe5 bestemme prosjektstruktur, redigeringstrender og arbeidsm\xf8nstre, og brukes ofte til morsom visualisering. Redditors bruker det til \xe5 visualisere kommentaraktivitet og kode-refactorings. Noen selskaper viser det til og med offentlig. Noen sliter med \xe5 finne praktiske bruksomr\xe5der, men synes det er givende som et refleksjonsverkt\xf8y. Estetisk tiltalende for mange."]}),"\n",(0,i.jsx)(r.h2,{id:"vis-generer-oppstartsideer-basert-p\xe5-discussion-service-kommentarer",children:"Vis Generer oppstartsideer basert p\xe5 Discussion Service-kommentarer."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://hn-ideas.tjcx.me/",children:"Original"}),".\nVi introduserer et nytt nettbasert verkt\xf8y som genererer oppstartsideer basert p\xe5 emner hentet fra kommentarer publisert p\xe5 Hacker News. Plattformen, som er utviklet av en person ved navn tjcx, lar brukerne skrive inn et emne og motta en tilfeldig oppstartside basert p\xe5 kommentarer knyttet til dette emnet. Denne oppfinnelsen kan vise seg \xe5 v\xe6re nyttig for \xe5 styrke gr\xfcndere og fremme innovasjon."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467917",children:"Discussion Service"}),".\nEn ny oppstartsidegenerator er opprettet ved hjelp av Discussion Service-kommentarer. Ideene spenner fra seri\xf8se til sarkastiske, inkludert en abonnementstjeneste for geiteblod og leiemordere. Kommentarene gj\xf8r narr av ideer, men foresl\xe5r ogs\xe5 plattformer for UBI og persontilpasset medisin. Andre forslag inkluderer treningsapper, temperaturoverv\xe5kingsenheter og VR for overv\xe5king av kj\xe6ledyr. Brukere p\xe5 Discussion Service foresl\xe5r et bredt spekter av oppstartsideer, inkludert kontroversielle ideer som barnelignende sexdukker og laboratoriedyrket menneskekj\xf8tt. Blandede resultater rapportert, med noen som synes det er morsomt og andre ikke s\xe5 nyttige. N\xf8yaktighet kritiseres, og politiske eller religi\xf8se kommentarer frar\xe5des."]}),"\n",(0,i.jsx)(r.h2,{id:"devops-bruker-en-kapasitetsmodell-ikke-en-modenhetsmodell",children:"DevOps bruker en kapasitetsmodell, ikke en modenhetsmodell."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://octopus.com/blog/devops-uses-capability-not-maturity",children:"Original"}),".\nDevOps b\xf8r bruke en kapasitetsmodell, ikke en modenhetsmodell, if\xf8lge Steve Fenton. I motsetning til en modenhetsmodell er tiln\xe6rmingen resultatbasert og oppmuntrer til eksperimentering med verkt\xf8y og prosesser. Den er SEM-basert, kan tilpasses og er dynamisk; den kan gi trinnvise gevinster ved \xe5 identifisere kapabiliteter. Modenhetsmodeller kan v\xe6re rigide, standardiserte og ikke ta hensyn til unike forretningsutfordringer. Kapasitetsmodellen kobler egenskaper til bredere systemresultater. Den strukturelle modellen er overveldende, men b\xf8r brukes til kontinuerlig forbedring."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35466718",children:"Discussion Service"}),'.\nDevOps transformerte utviklerteamets roller og presset h\xf8yere SysAdmin-ferdighetsniv\xe5er. Noen foresl\xe5r alternative begreper som "plattformteknikk". Metrikkbasert kapasitetsmodell kritisert som en salgspitch, krever meningsfulle evner. Dyrk en kultur for \xe5 pr\xf8ve nye ting for forretningsutvikling.']}),"\n",(0,i.jsx)(r.h2,{id:"det-er-ingen-enkel-oppgave-\xe5-\xf8ke-kapasiteten-i-str\xf8mnettet",children:"Det er ingen enkel oppgave \xe5 \xf8ke kapasiteten i str\xf8mnettet."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.economist.com/technology-quarterly/2023/04/05/adding-capacity-to-the-electricity-grid-is-not-a-simple-task",children:"Original"}),".\nElektrisitetsnettet st\xe5r overfor utfordringer n\xe5r det gjelder \xe5 integrere fornybare kilder, med f\xe5 leverand\xf8rer som er villige til \xe5 utvide transformatorkapasiteten. Konservativ regulering og utilstrekkelige nettforbindelser begrenser markedsandelen for fornybar energi, noe som f\xf8rer til forsinkelser og usikkerhet i nye prosjekter. Tilsynsmyndighetene erkjenner behovet for langdistansetilkoblinger for avkarbonisering av nettet, med nye forskrifter for \xe5 st\xf8tte prosjekter for fornybar energi. India planlegger \xe5 koble til 500 GW fornybar kapasitet innen 2030, mens Kina nyter godt av den nylige nettutbyggingen. Det er imidlertid fortsatt avgj\xf8rende \xe5 optimalisere k\xf8styring og planleggingsprosedyrer, ettersom bygging av nettinfrastruktur m\xe5 balansere delikate avveininger."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35463182",children:"Discussion Service"}),".\n\xc5 \xf8ke kapasiteten i str\xf8mnettet byr p\xe5 utfordringer n\xe5r det gjelder tillatelser, milj\xf8lovgivning, eiendomsrett, ekspropriasjon og \xe5 finne uregistrerte eiere. Landene st\xe5r overfor unike nettproblemer, blant annet S\xf8r-Afrikas fors\xf8mte kraftnett og Nederlands nettkapasitet som ikke klarer \xe5 holde tritt med investeringene. Gammel nettinfrastruktur gjenbrukes til nye havvindparker i Storbritannia, men mange gr\xf8nne prosjekter har datoer p\xe5 2030-tallet. Stabilitet i nettet kontra fremme av fornybare energikilder og behovet for hydrogen til energilagring diskuteres. Utfordringene med fornybar energi omfatter overbygging, lagring og tilkobling til nettet. S\xf8r-Afrikanere har f\xe6rre str\xf8mbrudd i land som Tyskland og \xd8sterrike. Kina er ledende innen likestr\xf8msoverf\xf8ring med ultrah\xf8y spenning. Fornybar energi har aldri v\xe6rt noe problem for nett, selv om syntetisk treghet og h\xe5ndtering av plutselige forsyningsfall fortsatt er en utfordring."]}),"\n",(0,i.jsx)(r.h2,{id:"vi-kunngj\xf8r-wcgi-webassembly-og-cgi",children:"Vi kunngj\xf8r WCGI: WebAssembly og CGI"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://wasmer.io/posts/announcing-wcgi",children:"Original"}),".\nWasmer har introdusert WCGI, en teknologi som kombinerer kraften til WebAssembly med enkelheten til CGI for utvikling p\xe5 serversiden. Den kan gjenbruke eksisterende CGI-applikasjoner, lage ultrasm\xe5 pakker med bare forretningslogikk og statiske ressurser, og kj\xf8rer WebAssembly-kode i en sandkasse. Det sikrer st\xf8rre effektivitet, sikkerhet og fleksibilitet i utvikling p\xe5 serversiden og har potensial til \xe5 omforme landskapet for serverl\xf8se applikasjoner. Webutviklere kan lage WCGI-applikasjoner med Rust og PHP ved \xe5 kompilere dem til Wasm, og WCGI-servere kan kj\xf8res ved hjelp av Wasmer CLI. Wasmer jobber kontinuerlig med \xe5 utvide WCGIs muligheter."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35469276",children:"Discussion Service"}),".\nWasmer.io kunngj\xf8r WCGI, som tillater s\xf8ml\xf8s integrasjon med eksisterende servere; Java Servlets vs. \xe5pne standarder; WebAssembly-l\xf8sninger utenfor nettleseren. Java-applets, GWT og JVM diskutert. WCGI har minneisolering, CGI-utgangskapasitet og eliminerer behovet for milj\xf8variabler. Wordpress-testing av ytelse p\xe5 WCGI. Utviklere bruker WASM og Wasmer for inkludering av opprinnelig kode, noe som reduserer forsinkelser og forbedrer portabiliteten. H\xf8y sikkerhet for app-ressursallokering og modulkontroll. Kj\xf8retidshastighet langsommere p\xe5 WebAssembly sammenlignet med native."]}),"\n",(0,i.jsx)(r.h2,{id:"json-vs-xml",children:"JSON vs. XML"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://corecursive.com/json-vs-xml-douglas-crockford/#",children:"Original"}),".\nDoug Crockford, skaperen av JSON, deler sin historie p\xe5 CoRecursive podcast og diskuterer sine kamper mot XML, historien til JavaScript og hans rolle i \xe5 gj\xf8re JSON til en standard. Han reflekterer ogs\xe5 over karrieren sin og oppfordrer utviklere til \xe5 omfavne nye paradigmer. Discussion Service-brukere deler sine erfaringer og tanker om ulike teknologirelaterte emner. Alt i alt gir disse innleggene verdifull innsikt for fagfolk som \xf8nsker \xe5 utvide kunnskapen sin."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467711",children:"Discussion Service"}),".\nEksperter diskuterer fordeler og ulemper med XML og JSON, og noen foretrekker XML for komplekse data, mens andre foresl\xe5r JSON p\xe5 grunn av dets enkelhet og utbredelse. Douglas Crockford er \xe6ret blant programmerere og har en spesiell plass i hjertene til JS-entusiaster. Brukere diskuterer fordeler og ulemper ved ulike dataformater og programmeringsspr\xe5k, uten noen klar l\xf8sning p\xe5 deres iboende avveininger. Til tross for debatten eksisterer ulike formater av en grunn og b\xf8r velges i henhold til situasjonsbestemte behov. Adam Bosworth hevder at HTMLs eksplosive utbredelse skyldtes dets begrensninger, ikke p\xe5 tross av dem, og at XML var for komplisert for vanlige brukere."]}),"\n",(0,i.jsx)(r.h2,{id:"nettstedet-ligger-p\xe5-en-24-\xe5r-gammel-linux-server",children:"Nettstedet ligger p\xe5 en 24 \xe5r gammel Linux-server."}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://raq.serialport.org/",children:"Original"}),".\nSiden det ikke er gitt noe r\xe5tekstinnhold, er jeg ikke i stand til \xe5 gi et sammendrag for denne oppgaven."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468637",children:"Discussion Service"}),".\nEn 24 \xe5r gammel Linux-server kj\xf8rer fortsatt med NetBSD og Apache og er vert for et nettsted. Brukerne mimrer om utdatert webteknologi, og noen foresl\xe5r nye m\xe5ter \xe5 implementere gjesteb\xf8ker eller visningsteller p\xe5. Det er ogs\xe5 diskusjon om samtidig filtilgang og samfunnets holdninger til programmering. \xc5 drifte et nettsted p\xe5 utdatert maskinvare er ikke praktisk for servering av sider i v\xe5r tid. Noen synes det er vanskelig \xe5 f\xe5 tilgang til serveren p\xe5 grunn av cloudflare."]}),"\n",(0,i.jsx)(r.h2,{id:"er-det-min-feil-hvis-du-ikke-takler-sannheten-2019",children:"Er det min feil hvis du ikke takler sannheten? (2019)"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://agileotter.blogspot.com/2019/09/is-it-my-fault-you-cant-handle-truth.html",children:"Original"}),".\nArtikkelen advarer mot farene ved overdreven rasjonalitet, og fremhever at det noen ganger er viktigere \xe5 v\xe6re hjelpsom enn \xe5 ha rett. Den forklarer hvordan overdrevent rasjonelle personer kan mangle empati og skape maktspill. Artikkelen siterer et eksempel p\xe5 en positiv probleml\xf8sningstiln\xe6rming og sp\xf8r leserne om \xe5 gjemme seg bak rasjonalitet for \xe5 unng\xe5 ansvar. Kommentarene i diskusjonen p\xe5 Hacker News omfatter temaer som produktivitet og smidig metodikk, der brukerne kommer inn p\xe5 rasjonalitet og bedriftsdysfunksjon. En bruker foresl\xe5r en bok om Agile som referanse. Ingen nye teknologier eller utgivelser ble nevnt."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35475482",children:"Discussion Service"}),".\nEn artikkel legger vekt p\xe5 \xe5 veilede i stedet for \xe5 fortelle folk sannheten, ettersom fakta ofte er ineffektive. Discussion Service-brukere diskuterer viktigheten av empati og kontekst, og reiser sp\xf8rsm\xe5l om \xe5 f\xe5 glede av sinne. Eksperter diskuterer balansen mellom \xe6rlighet og vennlighet, og behovet for empati, respekt og vitenskapelig stringens. Debatten dreier seg om vitenskapens form\xe5l, sannhetss\xf8ken og spillteori. Effektiv kommunikasjon av sannhet krever takt, timing og relasjonsbygging, ettersom fors\xf8mmelse f\xf8rer til grusomhet og maktkamp. Noen hevder at objektiv sannhet i noen sammenhenger kan v\xe6re respektl\xf8st, og at det \xe5 anta \xe9n sannhet er feil."]}),"\n",(0,i.jsx)(r.h2,{id:"c-strings-og-min-langsomme-nedstigning-til-galskap",children:"C Strings og min langsomme nedstigning til galskap"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.deusinmachina.net/p/c-strings-and-my-slow-descent-to",children:"Original"}),".\nDiego Crespo diskuterer C String-manipulasjon og vanlige funksjoner som strcpy og strlen, og de potensielle problemene som oppst\xe5r ved \xe5 jobbe med disse funksjonene. Utfordringene ved \xe5 arbeide med ikke-latinske spr\xe5k, spesielt Unicode og UTF-8-koding, beskrives i detalj med mulige l\xf8sninger. Viktigheten av \xe5 v\xe6re forsiktig n\xe5r man arbeider med C-strenger, for \xe5 unng\xe5 udefinert oppf\xf8rsel og potensielle angrep, understrekes. Crespo bemerker ogs\xe5 at C++ unng\xe5r noen av disse problemene ved \xe5 behandle strenger som objekter. Leserne oppfordres til \xe5 sjekke ut forfatterens kontoer p\xe5 sosiale medier og artikler om programmeringsspr\xe5k og lavniv\xe5koding."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467367",children:"Discussion Service"}),".\nDiscussion Service-brukere diskuterer iboende sikkerhetsproblemer i C-strengh\xe5ndtering, foresl\xe5r bruk av alternative biblioteker og fremhever behovet for bedre minneh\xe5ndtering. Praktisk bruk av C for strengbehandling diskuteres, og noen anbefaler allokatorer eller containere. Standard C-biblioteker kritiseres for ineffektivitet, og brukere foresl\xe5r \xe5 endre navn p\xe5 strlen-funksjonen for bedre lesbarhet. Kommentarer dekker ogs\xe5 feil for\xe5rsaket av strncpy() og nyanser av Unicode. C-entusiaster forsvarer spr\xe5kets tilgang og kontroll, mens andre synes det er for komplekst, og diskuterer forskjellige metoder for \xe5 h\xe5ndtere strenger i C. R\xe5d tilbys for \xe5 unng\xe5 vanlige fallgruver ved C-strengh\xe5ndtering. Frustrasjon uttrykt, og alternative strengbiblioteker foresl\xe5tt fremfor vanlige arrays. Til tross for populariteten til C, mangler det en effektiv l\xf8sning for strengh\xe5ndtering."]}),"\n",(0,i.jsx)(r.h2,{id:"mutexprotected-et-c-m\xf8nster-for-enklere-samtidighet",children:"MutexProtected: Et C++-m\xf8nster for enklere samtidighet"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://awesomekling.github.io/MutexProtected-A-C++-Pattern-for-Easier-Concurrency/",children:"Original"}),".\nArtikkelen forklarer utfordringene med \xe5 programmere samtidige applikasjoner ved hjelp av l\xe5ser og presenterer et C++-m\xf8nster kalt MutexProtected som forenkler denne prosessen. Forfatteren bruker et eksempel i C for \xe5 demonstrere behovet for MutexProtected og forbereder et barebone-eksempel. Artikkelen introduserer deretter en C++ RAII-klasse for \xe5 l\xf8se problemet med glemt mutex-oppl\xe5sing, men viser manglene. Forfatteren presenterer deretter MutexProtected som en kraftig konstruksjon som kombinerer en mutex og datatype for \xe5 sikre korrekt samtidig tilgang til data. Artikkelen avsluttes med introduksjonen av MemoizedTreeMap, en implementering av et trebasert kart som bruker MutexProtected for \xe5 sikre tr\xe5dsikkerhet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35464152",children:"Discussion Service"}),".\nMutexProtected er et C++-m\xf8nster for enkel samtidighet som Rusts mutexer. Boost.synchronized er komplekst, men kan brukes header-only. Kommentarer foresl\xe5r lambda- og RAII-stil eller eksplisitt l\xe5sing og oppl\xe5sing, og scoped_lock for flere l\xe5ser. Eksperter diskuterer mutekser versus kanaler for samtidighet."]}),"\n",(0,i.jsx)(r.h2,{id:"clarence-thomas-og-milliard\xe6ren",children:"Clarence Thomas og milliard\xe6ren"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.propublica.org/article/clarence-thomas-scotus-undisclosed-luxury-travel-gifts-crow",children:"Original"}),".\nProPublica rapporterer at Justice Clarence Thomas angivelig aksepterte luksusturer fra den republikanske donoren Harlan Crow i over to ti\xe5r, uten \xe5 avsl\xf8re dem p\xe5 \xe5rlige \xf8konomiske opplysninger, noe som reiser etiske bekymringer. Crow, som har brukt millioner p\xe5 konservativ politikk, eier en yacht og et privat jetfly som Thomas har reist med, og har v\xe6rt vertskap for ham p\xe5 sin ranch og sitt private feriested i Texas. Crows tilgang til rettsvesenet omfatter alle forretningsmannen velger \xe5 invitere med seg, noe som kan v\xe6re i strid med offentlighetsloven. Den oppdaterte etiske veiledningen for dommere presiserer at offentliggj\xf8ring er n\xf8dvendig for slike opphold, inkludert en tur i 2021 til en katolsk kirkeg\xe5rd n\xe6r New York City der en bronsestatue av Thomas '\xe5ttendeklassel\xe6rer ble avduket med finansiering fra Crow."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35467948",children:"Discussion Service"}),".\nEn viktig amerikansk h\xf8yesterettsdommer kan v\xe6re innblandet i betydelig korrupsjon ettersom han kan ha mottatt ulovlige tjenester fra en milliard\xe6r; det er imidlertid lite sannsynlig at disse handlingene vil f\xf8re til en riksrettssak i dagens ultrapolitiske klima. Selv om dommer Thomas kanskje ikke er bundet av lavere domstolers etiske regler, kan det fortsatt bli tatt rettslige skritt, inkludert en etterforskning fra justisdepartementet eller skattemyndighetene. Den \xe5penbare korrupsjonen i rettsvesenet fremhever de superrikes korrumperende innflytelse p\xe5 offentlige institusjoner, med forutsigbar suksess s\xe5 langt. Til tross for at Thomas' handlinger \xe5penbart er i strid med loven, kan han slippe straff, delvis fordi han nekter \xe5 stille makthaverne til ansvar."]}),"\n",(0,i.jsx)(r.h2,{id:"rusts-d\xe5rlige-komposisjonsevne",children:"Rusts d\xe5rlige komposisjonsevne"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://thedav.is/post/rusts-poor-composability/",children:"Original"}),".\nForfatteren diskuterer Rusts d\xe5rlige komponerbarhet, fremhever syntaksproblemer med for-l\xf8kker og iteratorer, og hvordan det p\xe5virker brukstilfeller i den virkelige verden; forfatteren kritiserer Rusts mangel p\xe5 fleksibilitet og komponerbarhet, og argumenterer for en nedgang i spr\xe5kutviklingen for \xe5 fokusere p\xe5 ergonomi; forfatteren nevner p\xe5g\xe5ende arbeid med generiske n\xf8kkelord og referanser for \xe5 forbedre komponerbarheten."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35468168",children:"Discussion Service"}),".\nBrukerne diskuterer Rusts komponerbarhet: noen roser dets allsidighet, andre kritiserer dets manglende fleksibilitet med iteratorer. Rusts kraft og typesystem beundres, men noen synes syntaksen er tungvint. Team b\xf8r fokusere p\xe5 ergonomi, selv om noen foresl\xe5r \xe5 bruke andre spr\xe5k hvis man ikke liker Rust. Discussion Service-tr\xe5den diskuterer Rusts programmeringsfallgruver, nedleggelser og iterative modell. Rusts syntaks, effekter system, og begrensninger med nedleggelser er kritisert. Komponerbarhetsproblemer oppst\xe5r med Rusts async closures og livstidsst\xf8tte. Rust eksperimenterer med generisk kode over sync+async, mens Goroutines og Zig har denne funksjonen."]}),"\n",(0,i.jsx)(r.h2,{id:"oppdage-og-unng\xe5-heap-fragmentering-i-rust-applikasjoner",children:"Oppdage og unng\xe5 heap-fragmentering i Rust-applikasjoner"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.svix.com/blog/heap-fragmentation-in-rust-applications/",children:"Original"}),".\nEt Rust-prosjekt m\xf8tte ubegrenset minnevekst sannsynligvis for\xe5rsaket av haugfragmentering, l\xf8st ved \xe5 bytte ut tildeleren med jemalloc for en bedre minneprofil. En benchmark.yml i prosjektets repo tester forskjellige innganger. Svix s\xf8ker Rust-eksperter for en skalerbar tjeneste for fellesskapet."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35469632",children:"Discussion Service"}),".\nEn artikkel diskuterer hvordan man kan unng\xe5 heap-fragmentering i Rust-applikasjoner, og foresl\xe5r at jemalloc kan hjelpe. Kommentarer foresl\xe5r komprimering av haug, h\xe5ndtak, tcmalloc. Valg av riktige heap-alternativer og avveininger diskuteres. \xc5pen kildekode-prosjekters markedsf\xf8ring og identifisering av haugfragmentering er notert. jemalloc anbefales for en HTTP-servers h\xf8ye minnebruk p\xe5 grunn av Rusts blokkallokering. Rusts type systemeffektivitet verdsatt, 99.999% SLA oppn\xe5dd gjennom testing og redundanser."]}),"\n",(0,i.jsx)(r.h2,{id:"v\xe6r-forsiktig-med-hva-du-tester-eller-distribuerer-til-vercel",children:"V\xe6r forsiktig med hva du tester eller distribuerer til Vercel"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://twitter.com/shoeboxdnb/status/1643639119824801793",children:"Original"}),".\nArtikkelen advarer om \xe5 v\xe6re forsiktig n\xe5r du tester eller distribuerer til Vercel, da det kan f\xf8re til en svartelistet IP. Brukere forteller om personlige erfaringer med Vercels IP-forbud, og nevner problemer med teamets produktivitet og kommunikasjon. Noen antyder at forbudet kan v\xe6re knyttet til Vercels misforst\xe5tte fors\xf8k p\xe5 \xe5 forhindre misbruk. L\xf8sninger inkluderer \xe5 kontakte kundest\xf8tte eller bytte til en annen tjeneste. En Discussion Service-kommentar fremhever viktigheten av sikkerhet i skyinfrastrukturen og riktig testing."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35474837",children:"Discussion Service"}),".\nVercel l\xf8ser faktureringsproblemer, utforsker bruksgrenser. Noen kritiserer refusjonsprosessen. Cloud kostnadsoptimalisering viktig. Vercel sammenlignet med AWS App Runner, andre billigere alternativer. Serverless kan f\xf8re til uventet fakturering."]}),"\n",(0,i.jsx)(r.h2,{id:"linux-64-bringer-apple-m2-tillegg-for-2022-macbook-og-mac-mini",children:"Linux 6.4 Bringer Apple M2-tillegg for 2022 MacBook og Mac Mini"}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.phoronix.com/news/Apple-M2-Device-Tree-Linux-6.4",children:"Original"}),".\nDevice Tree (DT) -tillegg for Apples M2-enheter, inkludert MacBook Air, MacBook Pro og Mac Mini, vil bli lagt til Linux 6.4. Hector Martin, Asahi Linuxs hovedutvikler, sendte inn Apple SoC DT-oppdateringer for k\xf8 i SoC-treet f\xf8r sammensl\xe5ingsvinduet \xe5pnet i slutten av m\xe5neden. \xc5 legge til Apple M2 Device Tree-serien og st\xf8tte for den essensielle maskinvaren til maskinene p\xe5 DT vil gi s\xe5rt tiltrengt oppstr\xf8ms kjernest\xf8tte for Apple M2. Enheten er imidlertid fortsatt ikke brukbar for sluttbrukere, og enkeltpersoner som \xf8nsker den beste Apple M1 / M2 Linux-opplevelsen, m\xe5 bruke en nedstr\xf8ms distribusjon som Asahi Linux."]}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35470392",children:"Discussion Service"}),".\nLinux 6.4 legger til Apple M2-st\xf8tte for 2022 MacBook / Mac Mini. Discussion Service-brukere sammenligner Linux / MacOS str\xf8mstyring. Asahi Linux enn\xe5 ikke en perfekt l\xf8sning. Noe spenning, men frustrasjon over kvaliteten p\xe5 kommentarene. Brukere beklager feilinformasjon / tull. Kvaliteten p\xe5 diskusjonen har forverret seg i et bestemt domene. En bruker foresl\xe5r \xe5 blokkere det. Resten av tr\xe5den virker up\xe5virket."]}),"\n",(0,i.jsx)(r.h2,{id:"illustrasjoner-av-usynlige-japanske-vedlikeholdstog-som-bare-kj\xf8rer-om-natten",children:'Illustrasjoner av "usynlige" japanske vedlikeholdstog som bare kj\xf8rer om natten.'}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"https://www.spoon-tamago.com/toei-project-unseen-maintenance-trains/",children:"Original"}),'.\nKunstneren Masami Onishi har illustrert Japans sjelden sete arbeidsstyrke av nattlige tog som utf\xf8rer vedlikeholdsarbeid p\xe5 spor og elektriske ledninger i de tidlige morgentimene, noe som sikrer jevn og uavbrutt tjeneste hele dagen. De detaljerte illustrasjonene av disse togene er en del av Tokyo Metropolitan Bureau of Transportation\'s Project Toei. De inkluderer "Rail Grinding Carriage" som jevner ut slitasje p\xe5 skinnene, og "Electric Inspection Carriage" som vurderer h\xf8yden, spenningen og tilstanden til elektriske luftledninger. Japans jernbaner har et bemerkelsesverdig lavt antall avsporinger, med bare to slike hendelser registrert over hele landet i 2018.']}),"\n",(0,i.jsxs)(r.p,{children:[(0,i.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35474895",children:"Discussion Service"}),'.\nIllustrasjoner av "usynlige" japanske vedlikeholdstog som bare arbeider om natten, fremhevet gjennom Project Toei. Lokalbefolkningen i New York kommenterer utilstrekkelig vedlikehold av T-banen d\xf8gnet rundt, og noen skylder p\xe5 utdaterte yrker som d\xf8roperat\xf8rer. Viser kontrasten mellom rene T-banevogner i Tokyo og d\xe5rlig vedlikehold i New York, noe som f\xf8rer til diskusjon om d\xe5rlig infrastruktur i andre amerikanske byer. Japanske jernbaner drar nytte av private investorer og statlig finansiering, i motsetning til amerikansk offentlig transport, som anses som et offentlig gode. Tokyo Metropolitan Government eier mange tog, som vedlikeholdes gjennom sofistikerte AI-systemer, med planer om \xe5 v\xe6re helt autonome innen 2032. Rushtiden i Tokyo er mindre ubehagelig enn i London eller New York, med reserverte sitteplasser.']})]})}function g(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(k,{...e})}):k(e)}}}]);